-- 앱 테이블 물리 DDL — Syncular 서버 저장용 (_sync_* 관리 컬럼 포함)
-- 재생성: node scripts/regen-ddl.mjs

CREATE TABLE IF NOT EXISTS "posts" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "public_id" TEXT NOT NULL, "author_id" TEXT NOT NULL, "author_name" TEXT NOT NULL, "author_avatar" TEXT NOT NULL, "types" TEXT NOT NULL, "mode" TEXT NOT NULL, "region" TEXT NOT NULL, "days" TEXT NOT NULL, "time_slot" TEXT NOT NULL, "capacity" INTEGER NOT NULL, "intro" TEXT NOT NULL, "deadline" TEXT NOT NULL, "status" TEXT NOT NULL, "updated_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "feed_items" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "public_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "user_name" TEXT NOT NULL, "avatar" TEXT NOT NULL, "mission_title" TEXT NOT NULL, "memo" TEXT NOT NULL, "photo" TEXT, "created_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "cheers" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "public_id" TEXT NOT NULL, "feed_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "cheer_type" TEXT NOT NULL, "created_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "user_profiles" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "public_id" TEXT NOT NULL, "display_name" TEXT NOT NULL, "avatar" TEXT NOT NULL, "interests" TEXT NOT NULL, "created_at_ms" INTEGER NOT NULL, "updated_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "applications" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "apply_scope" TEXT NOT NULL, "post_id" TEXT NOT NULL, "group_id" TEXT NOT NULL, "applicant_id" TEXT NOT NULL, "applicant_name" TEXT NOT NULL, "applicant_avatar" TEXT NOT NULL, "status" TEXT NOT NULL, "message" TEXT NOT NULL, "updated_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "group_members" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "group_id" TEXT NOT NULL, "post_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "role" TEXT NOT NULL, "joined_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "verifications" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "verify_scope" TEXT NOT NULL, "group_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "mission_id" TEXT NOT NULL, "mission_title" TEXT NOT NULL, "mission_kind" TEXT NOT NULL, "date" TEXT NOT NULL, "memo" TEXT NOT NULL, "photo" TEXT, "created_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "missions" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "kind" TEXT NOT NULL, "date" TEXT, "week_key" TEXT, "title" TEXT NOT NULL, "goal" INTEGER NOT NULL, "status" TEXT NOT NULL, "verified_at_ms" INTEGER, "updated_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "point_ledger" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "amount" INTEGER NOT NULL, "reason" TEXT NOT NULL, "balance_after" INTEGER NOT NULL, "created_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "streaks" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "current" INTEGER NOT NULL, "best" INTEGER NOT NULL, "last_date" TEXT, "lottery_used_week" TEXT, "updated_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));

CREATE TABLE IF NOT EXISTS "badges" ("_sync_partition" TEXT NOT NULL, "_sync_row_id" TEXT NOT NULL, "id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "badge_id" TEXT NOT NULL, "earned_at_ms" INTEGER NOT NULL, "_sync_server_version" INTEGER NOT NULL, "_sync_scopes" TEXT NOT NULL, "_sync_payload" BLOB NOT NULL, PRIMARY KEY ("_sync_partition", "_sync_row_id"));
